from lib import *
S = SS('g5')
def tail(lines, sub):
    i = [k for k, l in enumerate(lines) if sub in l][0]
    return lines[i:]
L3 = S(3)
steps = [
    step("字符串是一个 16 字节的 {指针, 长度} 头:unsafe.Sizeof(string) = 16,头里的 len 等于 len(s),StringData(s) 就是头里的指针。切子串 s[7:10] 不拷贝:它的数据指针比 s 大 7 个字节、共用同一块内存;strings.Clone 才会拷贝一份(数据指针与原来不同)。两个相同的字符串字面量指向同一块数据,运行时拼出来的同内容字符串则不同。", t=tl(S(1)), done=lidx(S(1), 'unsafe.Sizeof(string) = 16', 'sub := s[7:10]'), mark=lidx(S(1), 'strings.Clone', '两个相同的字符串字面量'), kv=KV([['string 头', '{指针, 长度} = 16 字节'], ['s[7:10]', '数据指针 = s 的 +7,共用内存'], ['strings.Clone(sub)', '数据指针不同(拷贝)'], ['两个相同字面量', '同一块数据'], ['运行时拼出的同内容字符串', '各自一块']], ['s[7:10]'])),
    step("互转到底拷不拷贝:string(b) 之后改 b[0],s 不变;[]byte(s) 之后改 b[0],s 不变——都拷贝了。unsafe.String(&b[0], len(b)) 不拷贝:改 b[0] 之后 s 跟着变成 \"Zbc\"。用 unsafe.Slice(unsafe.StringData(s), len(s)) 拿到指向字符串字面量的 []byte 后写入 b[0]:进程以 rc=2 退出,输出 unexpected fault address、fatal error: fault、signal SIGBUS——字面量在只读内存里。", t=tl(S(2)), done=lidx(S(2), 'string(b) 拷贝了', '[]byte(s) 拷贝了'), mark=lidx(S(2), 'unsafe.String(&b[0]', 'rc=2'), kv=KV([['string(b)', '拷贝:改 b 后 s 不变'], ['[]byte(s)', '拷贝:改 b 后 s 不变'], ['unsafe.String(&b[0], len(b))', '不拷贝:改 b 后 s 也变'], ['写字面量的 unsafe.Slice', 'rc=2,SIGBUS,fatal error: fault']], ['写字面量的 unsafe.Slice'])),
    step("真实分配次数(AllocsPerRun):结果逃逸的 []byte(long)、string(lb)、\"x\" + string(lb)、strings.Clone 都是 1 次;[]byte(long) 不逃逸只读是 0 次(包括 100 字节),m[string(lb)]、string(lb) == long、for range []byte(long) 都是 0 次。不逃逸的 string(b):10 字节 0 次、100 字节 1 次。扫大小:[]byte(s) 在 10、32、33、100、1000 字节都是 0 次;string(b) 在 10、32 字节是 0 次,33、100、1000 字节是 1 次。", t=tl(L3), done=lidx(L3, 'm[string(lb)]', 'string(lb) == long', 'for range []byte(long)', '[]byte(long)  不逃逸'), mark=lidx(L3, '33 字节', '100 字节', '1000 字节', '结果逃逸'), b=bars([['string(b) 不逃逸 32 字节', 0, '0 次'], ['string(b) 不逃逸 33 字节', 1, '1 次'], ['[]byte(s) 不逃逸 1000 字节', 0, '0 次'], ['[]byte(s) 逃逸 100 字节', 1, '1 次']], 1, done=[0, 2], mark=[1, 3]), kv=KV([['结果逃逸的转换 / 拼接 / Clone', '1 次'], ['m[string(b)]、string(b) == s、for range []byte(s)', '0 次'], ['不逃逸的 string(b)', '≤32 字节 0 次,≥33 字节 1 次'], ['不逃逸的 []byte(s)(只读)', '1000 字节也是 0 次']], ['不逃逸的 string(b)'])),
    step("子串拖住整块内存:分配 10 MiB 字符串,只留 big[:5] 并 GC:HeapAlloc 从基线 0.20 MiB 涨到 10.20 MiB(keep 只有 5 个字节,但整块 10 MiB 仍被引用);keep = strings.Clone(keep) 再 GC:回到 0.20 MiB。", t=tl(S(4)), done=lidx(S(4), '基线 HeapAlloc'), mark=lidx(S(4), 'strings.Clone(keep)'), b=bars([['基线', 0.20, '0.20 MiB'], ['只留 big[:5]', 10.20, '10.20 MiB'], ['Clone 之后', 0.20, '0.20 MiB']], 10.20, done=[0, 2], mark=[1]), kv=KV([['基线 HeapAlloc', '0.20 MiB'], ['只留 big[:5]', '10.20 MiB'], ['Clone 之后', '0.20 MiB']], ['只留 big[:5]'])),
    step("为什么只读的 []byte(s) 不拷贝:-gcflags=-m 对 toBytesRead 打印 zero-copy string->[]byte conversion,只读版本 10、32、33、1000 字节都是 0 次;写入版本(x[0] = 1)10、32 字节 0 次,33、1000 字节 1 次。加 -d=zerocopy=0 关掉这项优化:诊断里没有 zero-copy 行,只读版本 33、1000 字节变成 1 次,写入版本不变。", t=tl(S(5)), done=lidx(S(5), '默认:', 'zero-copy string->[]byte conversion', '  10 字节', '  32 字节'), mark=lidx(S(5), '-d=zerocopy=0', '33 字节', '1000 字节'), b=bars([['只读 33 字节(默认)', 0, '0 次'], ['写入 33 字节(默认)', 1, '1 次'], ['只读 33 字节(zerocopy=0)', 1, '1 次']], 1, done=[0], mark=[1, 2]), kv=KV([['默认,只读版本', '10 / 32 / 33 / 1000 字节都是 0 次'], ['默认,写入版本', '≤32 字节 0 次,33 / 1000 字节 1 次'], ['-d=zerocopy=0,只读版本', '33 / 1000 字节变成 1 次']], ['-d=zerocopy=0,只读版本'])),
]
A = mkartg('g5', 5, 'Go,字符串,[]byte,unsafe,内存分配,真实验证,动画演示',
    '用 Go 1.27.1 读字符串的 16 字节头并实测转换:子串与原串共用内存,string(b) 与 []byte(s) 默认拷贝,unsafe.String 不拷贝而写字面量会 SIGBUS;不逃逸的 string(b) 在 32 字节以内零分配,[]byte(s) 在结果从不被修改时由编译器“zero-copy”(1000 字节也是 0 次,-d=zerocopy=0 关掉后变成 1 次);m[string(b)] 与 string(b) == s 零分配;10 MiB 字符串只留 5 字节的子串会让堆保持 10.20 MiB。',
    '字符串的转换到底拷不拷贝,取决于结果会不会被修改、会不会逃逸,以及多大。这篇用 unsafe 读字符串头,再逐一验证互转的拷贝与分配行为,最后看一个常见的内存泄漏形态:一个很小的子串拖住整块大字符串。',
    [('16 字节', 'string 头 = {指针, 长度},子串与原串共用同一块内存'), ('32 字节', '不逃逸的 string(b) 在 32 字节以内 0 次分配,33 字节起 1 次(实测)'), ('10.20 MiB', '只留 10 MiB 字符串的 5 字节子串时的堆;Clone 之后回到 0.20 MiB')],
    [('字符串头与子串', '<p><code>string</code> 在运行时是一个 <code>{指针, 长度}</code> 头,所以切子串是 O(1) 的,只改指针与长度。代价就是第四节的现象:子串继续引用整块底层内存。字面量放在二进制的只读数据里,相同的字面量会合并成同一份。</p>'),
     ('互转与 unsafe', '<p>安全的转换总是拷贝。<code>unsafe.String</code> 与 <code>unsafe.Slice(unsafe.StringData(s), …)</code> 不拷贝,但要自己保证两个条件:不再修改被共享的字节,并且不要写字符串字面量所在的只读内存(上面实测会以 SIGBUS 崩溃)。</p>'),
     ('什么时候真的分配', '<p>读编译器源码得到一个线索:不逃逸的转换会用栈上的临时缓冲,缓冲大小常量 <code>tmpStringBufSize</code> 是 32(<code>runtime/string.go</code>),实测 <code>string(b)</code> 正好在 32 与 33 字节之间变成 1 次分配。另外三种常见写法零分配:<code>m[string(b)]</code>、<code>string(b) == s</code>、<code>for range []byte(s)</code>——编译器不为它们建立真正的字符串。注意 <code>[]byte(s)</code> 在不逃逸时即使 1000 字节也是 0 次,原因见最后一节。</p>'),
     ('子串拖住大内存', '<p>这是真实项目里常见的“泄漏”:从一个大响应、大文件内容里切出一小段长期保存。<code>strings.Clone</code>(或 <code>string([]byte(s[:n]))</code> 之类会拷贝的写法)能让大块在下次 GC 后释放。数字来自 <code>runtime.ReadMemStats</code> 的 <code>HeapAlloc</code>,每次先调用 <code>runtime.GC()</code>。</p>'),
     ('zero-copy:[]byte(s) 不拷贝的情形', '<p>编译器源码 <code>escape/escape.go</code> 里有这样一段:字符串转 <code>[]byte</code> 的结果如果从不被修改(没有 <code>attrMutates</code>),就把它改成直接复用字符串内存的版本,诊断里叫 <code>zero-copy string->[]byte conversion</code>。上面的实验与它吻合:只读版本零分配,一旦写入就回到“≤32 字节用栈缓冲、更大才分配”;<code>-d=zerocopy=0</code> 把这项优化关掉,只读版本 33 字节以上就变成 1 次分配。这个例子里的结果既不修改也不逃逸,条件变化时是否仍然成立我没有逐一验证。</p>')],
    steps,
    [ENV_G + '。读过的源码:runtime/string.go(tmpStringBufSize = 32)、cmd/compile/internal/walk/convert.go(walkStringToBytes)、cmd/compile/internal/escape/escape.go(zero-copy 的条件);用 unsafe 读字符串头,写字面量的实验单独起一个进程;堆的数字来自 runtime.ReadMemStats,每次先 GC;分配次数来自 testing.AllocsPerRun(1000 次)',
     '没有验证:amd64 与其它版本的编译器是否同样的阈值、string(b) 的临时缓冲在 slicebytetostring 里的实现细节、[]rune 转换、字符串拼接的 concatstrings 缓冲、字符串 intern 或 unique 包、cgo 的 C.GoString 拷贝'],
    '字符串的内部结构')
